<?php require 'config.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'){ $s=$pdo->prepare('SELECT ci.quantity,p.id,p.name,p.price,p.stock FROM cart_items ci JOIN products p ON p.id=ci.product_id WHERE ci.user_id=?');$s->execute([user()['id']]);$items=$s->fetchAll();if(!$items){flash('ตะกร้าสินค้าว่าง');header('Location: cart.php');exit;} $total=0;foreach($items as $i){if($i['quantity']>$i['stock']){flash('สินค้า '.$i['name'].' มีจำนวนไม่พอ');header('Location: cart.php');exit;}$total+=$i['quantity']*$i['price'];} $name=trim($_POST['shipping_name']??'');$phone=trim($_POST['shipping_phone']??'');$address=trim($_POST['shipping_address']??'');$pay=$_POST['payment_method']??'โอนเงิน';if(!$name||!$phone||!$address){flash('กรุณากรอกข้อมูลจัดส่งให้ครบ');header('Location: checkout.php');exit;}try{$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO orders(user_id,total,shipping_name,shipping_phone,shipping_address,payment_method) VALUES(?,?,?,?,?,?)');$s->execute([user()['id'],$total,$name,$phone,$address,$pay]);$oid=$pdo->lastInsertId();foreach($items as $i){$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,price,quantity) VALUES(?,?,?,?,?)')->execute([$oid,$i['id'],$i['name'],$i['price'],$i['quantity']]);$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$i['quantity'],$i['id']]);} $pdo->prepare('DELETE FROM cart_items WHERE user_id=?')->execute([user()['id']]);$pdo->commit();$pdo->prepare('INSERT INTO activity_logs(user_id,action,details) VALUES(?,?,?)')->execute([user()['id'],'สั่งซื้อสินค้า','Order #'.$oid]);flash('สั่งซื้อเรียบร้อย เลขที่คำสั่งซื้อ #'.$oid);header('Location: orders.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('เกิดข้อผิดพลาดระหว่างสั่งซื้อ');header('Location: checkout.php');exit;}}require 'header.php';$s=$pdo->prepare('SELECT ci.quantity,p.price FROM cart_items ci JOIN products p ON p.id=ci.product_id WHERE ci.user_id=?');$s->execute([user()['id']]);$total=0;foreach($s->fetchAll() as $i)$total+=$i['quantity']*$i['price'];?>
<div class="form-card"><h1>ข้อมูลจัดส่ง</h1><p class="price">ยอดชำระ: ฿<?=money($total)?></p><form method="post"><div class="field"><label>ชื่อผู้รับ</label><input name="shipping_name" value="<?=h(user()['name'])?>" required></div><div class="field"><label>เบอร์โทร</label><input name="shipping_phone" required></div><div class="field"><label>ที่อยู่จัดส่ง</label><textarea name="shipping_address" rows="4" required></textarea></div><div class="field"><label>วิธีชำระเงิน</label><select name="payment_method"><option>โอนเงิน</option><option>เก็บเงินปลายทาง</option></select></div><button class="btn" style="width:100%">ยืนยันคำสั่งซื้อ</button></form></div><?php require 'footer.php';?>
